findings.codeql_raw_query:
/**
 * @name Regular Expression Denial of Service (ReDoS)
 * @description Identifies potentially vulnerable regular expressions that could lead to ReDoS attacks
 * @kind problem
 * @problem.severity warning
 * @id py/yarl-redos
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.ApiGraphs

from Expr regex
where
  (
    // regex.compile or re.compile
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember("compile").getACall() and
      regex = call.getArg(0).asExpr()
    )
    or
    // re.match, re.search, re.findall, etc with pattern
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["match", "search", "findall", "finditer", "sub", "subn", "split"]).getACall() and
      regex = call.getArg(0).asExpr()
    )
  ) and
  // Check for potentially problematic patterns (nested quantifiers, alternation with overlap)
  exists(StrConst pattern |
    pattern = regex and
    (
      // Nested quantifiers like (a+)+ or (a*)* or (a*)+
      pattern.getText().regexpMatch(".*\\([^)]*[*+]\\)[*+].*") or
      // Multiple consecutive quantifiers
      pattern.getText().regexpMatch(".*[*+]{2,}.*") or
      // Overlapping alternation patterns
      pattern.getText().regexpMatch(".*(\\||\\[)[^|\\]]*[*+][^|\\]]*[*+].*")
    )
  )
select regex, "Regular expression may be vulnerable to ReDoS attacks with malicious input."
